def replace_once(text: str, old: str, new: str, label: str) -> str:
    if new in text:
        return text
    if old not in text:
        raise SystemExit(f"Missing v211 bank patch target: {label}")
    return text.replace(old, new, 1)


def main() -> None:
    if not JS.exists():
        raise SystemExit(f"Missing cognitive runtime: {JS}")
    text = JS.read_text(encoding="utf-8")

    old_fingerprint = "const prompt=String(data.prompt||'');if(/undefined|NaN/.test(prompt))throw new Error(`Invalid prompt value: ${d.slug}`);const fingerprint=String([...`${d.slug}|${stage}|${prompt}|${answer}`].reduce((h,c)=>Math.imul(h^c.codePointAt(0),16777619)>>>0,2166136261));"
    new_fingerprint = "const prompt=String(data.prompt||''),study=String(data.study||''),meta=[data.stimulusWord||'',data.stimulusInk||'',data.stimulusRule||'',data.bindingDirection||'',data.temporalDirection||'',data.visualChangeFeature||'',data.visualChangePosition||'',data.visualChangeSetSize||''].join('|');if(/undefined|NaN/.test(prompt)||/undefined|NaN/.test(study))throw new Error(`Invalid prompt value: ${d.slug}`);const fingerprint=String([...`${d.slug}|${stage}|${study}|${prompt}|${answer}|${meta}`].reduce((h,c)=>Math.imul(h^c.codePointAt(0),16777619)>>>0,2166136261));"
    text = replace_once(text, old_fingerprint, new_fingerprint, "study-aware fingerprint")

    signature = "function makeTrial(d,stage,index,sessionSeed=0){const mode=d.mode||d.category||'',slug=d.slug||'',rnd=seeded(((d.slug.length+11)*1009+stage*10007+index*7919+(Number(sessionSeed)||0))>>>0),ri=(a,b)=>a+Math.floor(rnd()*(b-a+1)),pick=a=>a[Math.floor(rnd()*a.length)],symbols=['●','▲','■','◆','★','⬟','✚','⬢'],arrows=['↑','→','↓','←'];"
    expanded_signature = signature + "const bankV211=v211BankData(d,stage,index,sessionSeed,rnd,ri,pick,symbols,arrows);if(bankV211)return v202Finish(d,stage,rnd,bankV211);"
    if "function v211BankData(" not in text:
        if signature not in text:
            raise SystemExit("Missing v211 makeTrial signature")
        text = text.replace(signature, BANK_FUNCTION + "\n" + expanded_signature, 1)
    elif expanded_signature not in text:
        text = replace_once(text, signature, expanded_signature, "v211 generator hook")

    JS.write_text(text, encoding="utf-8")
    report = {
        "version": 211,
        "status": "built-not-published",
        "study_aware_fingerprint": True,
        "expanded_modes": [
            "simple_reaction", "choice_reaction", "auditory_symbol", "response_inhibition",
            "conditional_reasoning", "context_clues", "emotion_recognition", "mental_rotation",
            "perspective_taking", "planning_steps", "priority_planning", "problem_solving",
            "word_categories", "semantic_fluency", "social_scenarios", "trail_switching",
            "verbal_analogy", "visual_reaction",
        ],
        "expanded_mode_count": 18,
        "minimum_empirical_stage_bank_target": 30,
        "session_repeat_guard_target": 0,
    }
    api = SITE / "api"
    api.mkdir(parents=True, exist_ok=True)
    (api / "cognitive-banks-v211.json").write_text(json.dumps(report, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(report, ensure_ascii=False, indent=2))


if __name__ == "__main__":
    main()
